}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 2}
\end{minipage}

\begin{minipage}[t]{0.44\linewidth}\vspace{0pt}Cho góc $\widehat{xOy} = 80^\circ$. Tia $Oz$ là tia phân giác của góc $\widehat{xOy}$ (hình vẽ). Số đo góc $\widehat{xOz}$ bằng:[[br]] \textbf{A.} $40^\circ$ \hspace{0.5cm} \textbf{B.} $80^\circ$ [[br]] \textbf{C.} $160^\circ$ \hspace{0.4cm} \textbf{D.} $50^\circ$\end{minipage}\hfill\begin{minipage}[t]{0.36\linewidth}\vspace{0pt}
\centering
\adjustbox{max width=\linewidth, max totalheight=2.4cm}{
\begin{tikzpicture}[line width=0.8pt, font=\small]
  \draw[ink] (0,0) -- (2.0,0) node[right]{$x$};
  \draw[ink] (0,0) -- (1.4,1.4) node[above right]{$y$};
  \draw[brand,line width=1.1pt] (0,0) -- (1.9,0.78) node[right]{$z$};
  \fill[ink] (0,0) circle (1.3pt) node[below left]{$O$};
  \node[font=\scriptsize] at (0.8,0.2) {$?^\circ$};
