\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 1}
\end{minipage}

\begin{minipage}[t]{0.44\linewidth}\vspace{0pt}Cho góc $\widehat{mOn} = 120^\circ$, tia $Ot$ là tia phân giác của $\widehat{mOn}$ (hình vẽ). Số đo góc $\widehat{tOn}$ bằng:[[br]] \textbf{A.} $60^\circ$ \hspace{0.5cm} \textbf{B.} $120^\circ$ [[br]] \textbf{C.} $30^\circ$ \hspace{0.5cm} \textbf{D.} $90^\circ$\end{minipage}\hfill\begin{minipage}[t]{0.36\linewidth}\vspace{0pt}
\centering
\adjustbox{max width=\linewidth, max totalheight=2.4cm}{
\begin{tikzpicture}[line width=0.8pt, font=\small]
  \draw[ink] (0,0) -- (1.8,0) node[right]{$n$};
  \draw[ink] (0,0) -- (-0.9,1.5) node[above left]{$m$};
  \draw[brand,line width=1.1pt] (0,0) -- (0.9,1.5) node[above right]{$t$};
  \fill[ink] (0,0) circle (1.3pt) node[below]{$O$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 2}
\end{minipage}

\begin{minipage}[t]{0.44\linewidth}\vspace{0pt}Cho tia $Oz$ là tia phân giác của góc $\widehat{xOy}$ (hình vẽ). Biết góc $\widehat{xOz} = 35^\circ$. Số đo góc $\widehat{xOy}$ bằng:[[br]] \textbf{A.} $70^\circ$ \hspace{0.5cm} \textbf{B.} $35^\circ$ [[br]] \textbf{C.} $140^\circ$ \hspace{0.4cm} \textbf{D.} $90^\circ$\end{minipage}\hfill\begin{minipage}[t]{0.36\linewidth}\vspace{0pt}
\centering
\adjustbox{max width=\linewidth, max totalheight=2.4cm}{
\begin{tikzpicture}[line width=0.8pt, font=\small]
