  \fill[ink] (0,0) circle (1.3pt) node[below left]{$O$};
  \node[font=\scriptsize] at (0.8,0.2) {$35^\circ$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 3}
\end{minipage}

\begin{minipage}[t]{0.44\linewidth}\vspace{0pt}Biết $Ot$ là tia phân giác của góc $\widehat{aOb}$ (hình vẽ) và $\widehat{aOt} = 45^\circ$. Góc $\widehat{aOb}$ là góc gì?[[br]] \textbf{A.} Góc vuông ($90^\circ$) \hspace{0.2cm} \textbf{B.} Góc nhọn ($45^\circ$) [[br]] \textbf{C.} Góc bẹt ($180^\circ$) \hspace{0.3cm} \textbf{D.} Góc tù ($135^\circ$)\end{minipage}\hfill\begin{minipage}[t]{0.36\linewidth}\vspace{0pt}
\centering
\adjustbox{max width=\linewidth, max totalheight=2.4cm}{
\begin{tikzpicture}[line width=0.8pt, font=\small]
