  \draw[ink] (0,0) -- (1.0,1.5) node[above right]{$y$};
  \draw[brand,line width=1.1pt] (0,0) -- (1.6,0.8) node[right]{$z$};
  \fill[ink] (0,0) circle (1.3pt) node[below left]{$O$};
  \node[font=\scriptsize] at (0.7,0.2) {$25^\circ$};
  \node[font=\scriptsize] at (0.5,0.7) {$25^\circ$};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 7}
\end{minipage}

\begin{minipage}[t]{0.44\linewidth}\vspace{0pt}Góc tạo bởi hai tia phân giác của hai góc kề bù (hình vẽ) có số đo bằng bao nhiêu?[[br]] \textbf{A.} $90^\circ$ \hspace{0.5cm} \textbf{B.} $180^\circ$ [[br]] \textbf{C.} $45^\circ$ \hspace{0.5cm} \textbf{D.} $60^\circ$\end{minipage}\hfill\begin{minipage}[t]{0.36\linewidth}\vspace{0pt}
